import TestimonialsSectionV4 from "./components/testimonials-section-v4"

export default function Page() {
  return <TestimonialsSectionV4 />
}

import { createBlockImage } from "@/lib/block-media"

import { TestimonialsSectionV4Root } from "./testimonials-section-v4-root"
import {
  testimonials as testimonialItems,
  type ResolvedTestimonial,
} from "../lib/testimonials-content"
import "../styles/testimonials-section-v4.css"

const blockImage = createBlockImage("testimonials-section-v4")

export default function TestimonialsSectionV4() {
  const testimonials: ResolvedTestimonial[] = testimonialItems.map((item) => {
    const { avatarFile, ...rest } = item
    return {
      ...rest,
      avatarSrc: blockImage(avatarFile),
    }
  })

  return <TestimonialsSectionV4Root testimonials={testimonials} />
}

"use client"

import { useEffect, useState } from "react"
import { ChevronLeftIcon, ChevronRightIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  Carousel,
  CarouselContent,
  CarouselItem,
  useCarousel,
} from "@/components/ui/carousel"

import type { ResolvedTestimonial } from "../lib/testimonials-content"
import TestimonialCard from "./testimonial-card"

const PAGE_SIZE = 3

function chunkTestimonials(items: ResolvedTestimonial[], size: number) {
  const pages: ResolvedTestimonial[][] = []
  for (let i = 0; i < items.length; i += size) {
    pages.push(items.slice(i, i + size))
  }
  return pages
}

function CarouselNav() {
  const { scrollPrev, scrollNext, canScrollPrev, canScrollNext } = useCarousel()

  return (
    <>
      <Button
        type="button"
        variant="default"
        size="icon-sm"
        className="absolute top-1/2 left-2 z-20 size-9 -translate-y-1/2 rounded-full bg-foreground text-background shadow-md hover:bg-foreground/90 disabled:opacity-40 md:left-3"
        disabled={!canScrollPrev}
        aria-label="Previous testimonials"
        onClick={scrollPrev}
      >
        <ChevronLeftIcon />
      </Button>
      <Button
        type="button"
        variant="default"
        size="icon-sm"
        className="absolute top-1/2 right-2 z-20 size-9 -translate-y-1/2 rounded-full bg-foreground text-background shadow-md hover:bg-foreground/90 disabled:opacity-40 md:right-3"
        disabled={!canScrollNext}
        aria-label="Next testimonials"
        onClick={scrollNext}
      >
        <ChevronRightIcon />
      </Button>
    </>
  )
}

function MobileCarousel({
  testimonials,
}: {
  testimonials: ResolvedTestimonial[]
}) {
  return (
    <Carousel opts={{ align: "start", loop: false }} className="w-full">
      <div className="relative">
        <CarouselContent className="ml-0">
          {testimonials.map((testimonial) => (
            <CarouselItem key={testimonial.id} className="basis-full pl-0">
              <TestimonialCard testimonial={testimonial} />
            </CarouselItem>
          ))}
        </CarouselContent>
        <CarouselNav />
      </div>
    </Carousel>
  )
}

function DesktopCarousel({ pages }: { pages: ResolvedTestimonial[][] }) {
  return (
    <Carousel opts={{ align: "start", loop: false }} className="w-full">
      <div className="relative overflow-hidden">
        <CarouselContent className="ml-0 touch-pan-y">
          {pages.map((page) => {
            const stops = page
              .map((item, index) => {
                const start = (index / page.length) * 100
                const end = ((index + 1) / page.length) * 100
                return `${item.shader.accent} ${start}% ${end}%`
              })
              .join(", ")

            return (
              <CarouselItem
                key={page.map((item) => item.id).join("-")}
                className="basis-full pl-0 transform-[translateZ(0)]"
              >
                <div
                  className="flex overflow-hidden backface-hidden transform-[translateZ(0)]"
                  style={{
                    backgroundImage: `linear-gradient(to right, ${stops})`,
                  }}
                >
                  {page.map((testimonial) => (
                    <div
                      key={testimonial.id}
                      className="relative min-w-0 basis-0 grow"
                    >
                      <TestimonialCard testimonial={testimonial} />
                    </div>
                  ))}
                </div>
              </CarouselItem>
            )
          })}
        </CarouselContent>
        <CarouselNav />
      </div>
    </Carousel>
  )
}

export default function TestimonialsCarousel({
  testimonials,
}: {
  testimonials: ResolvedTestimonial[]
}) {
  const [isDesktop, setIsDesktop] = useState<boolean | null>(null)
  const pages = chunkTestimonials(testimonials, PAGE_SIZE)

  useEffect(() => {
    const media = window.matchMedia("(min-width: 768px)")
    const update = () => setIsDesktop(media.matches)
    update()
    media.addEventListener("change", update)
    return () => media.removeEventListener("change", update)
  }, [])

  if (isDesktop === null) {
    const preview = testimonials.slice(0, PAGE_SIZE)
    const stops = preview
      .map((item, index) => {
        const start = (index / preview.length) * 100
        const end = ((index + 1) / preview.length) * 100
        return `${item.shader.accent} ${start}% ${end}%`
      })
      .join(", ")

    return (
      <div
        className="flex overflow-hidden"
        style={{ backgroundImage: `linear-gradient(to right, ${stops})` }}
      >
        {preview.map((testimonial, index) => (
          <div
            key={testimonial.id}
            className={
              index === 0
                ? "min-w-0 basis-0 grow"
                : "hidden min-w-0 basis-0 grow md:block"
            }
          >
            <TestimonialCard testimonial={testimonial} />
          </div>
        ))}
      </div>
    )
  }

  return isDesktop ? (
    <DesktopCarousel pages={pages} />
  ) : (
    <MobileCarousel testimonials={testimonials} />
  )
}

"use client"

import { useEffect, useLayoutEffect, useRef, useState } from "react"
import { GrainGradient } from "@paper-design/shaders-react"

import type { GrainShaderTheme } from "../lib/testimonials-content"

type ShaderViewport = {
  width: number
  height: number
  dpr: number
  ready: boolean
}

const initialViewport: ShaderViewport = {
  width: 0,
  height: 0,
  dpr: 1,
  ready: false,
}

const DESIGN_FALLBACK = { width: 480, height: 720 } as const

function adaptShader(theme: GrainShaderTheme, viewport: ShaderViewport) {
  const designWidth = theme.designWidth ?? DESIGN_FALLBACK.width
  const designHeight = theme.designHeight ?? DESIGN_FALLBACK.height

  const width = Math.max(1, Math.round(viewport.width * viewport.dpr))
  const height = Math.max(1, Math.round(viewport.height * viewport.dpr))

  const sizeRatio = Math.min(
    viewport.width / designWidth,
    viewport.height / designHeight
  )

  return {
    colors: theme.colors,
    colorBack: theme.colorBack,
    softness: theme.softness,
    intensity: theme.intensity,
    noise: theme.noise,
    shape: theme.shape,
    speed: theme.speed,
    width,
    height,
    ...(theme.scale !== undefined
      ? { scale: theme.scale * sizeRatio }
      : {}),
  }
}

function usePrefersReducedMotion() {
  const [reduced, setReduced] = useState(() =>
    typeof window === "undefined"
      ? false
      : window.matchMedia("(prefers-reduced-motion: reduce)").matches
  )

  useEffect(() => {
    const mql = window.matchMedia("(prefers-reduced-motion: reduce)")
    const onChange = () => setReduced(mql.matches)
    mql.addEventListener("change", onChange)
    return () => mql.removeEventListener("change", onChange)
  }, [])

  return reduced
}

export function TestimonialShader({ theme }: { theme: GrainShaderTheme }) {
  const ref = useRef<HTMLDivElement>(null)
  const [viewport, setViewport] = useState<ShaderViewport>(initialViewport)
  const [isVisible, setIsVisible] = useState(false)
  const reducedMotion = usePrefersReducedMotion()

  useLayoutEffect(() => {
    const el = ref.current
    if (!el) return

    const update = () => {
      const { width, height } = el.getBoundingClientRect()
      if (width < 1 || height < 1) return
      setViewport({
        width,
        height,
        dpr: Math.min(window.devicePixelRatio || 1, 2),
        ready: true,
      })
    }

    update()
    const resizeObserver = new ResizeObserver(update)
    resizeObserver.observe(el)

    const intersectionObserver = new IntersectionObserver(
      ([entry]) => setIsVisible(entry.isIntersecting),
      { rootMargin: "200px" }
    )
    intersectionObserver.observe(el)

    return () => {
      resizeObserver.disconnect()
      intersectionObserver.disconnect()
    }
  }, [])

  const shouldRender = viewport.ready && isVisible && !reducedMotion
  const renderProps = shouldRender ? adaptShader(theme, viewport) : null

  return (
    <div
      ref={ref}
      className="ts4-shader-frame"
      style={{ backgroundColor: theme.accent }}
      aria-hidden
    >
      {renderProps ? (
        <GrainGradient
          className="ts4-shader-canvas"
          colors={[...renderProps.colors]}
          colorBack={theme.accent}
          fit="cover"
          height={renderProps.height}
          intensity={renderProps.intensity}
          noise={renderProps.noise}
          {...(renderProps.scale !== undefined
            ? { scale: renderProps.scale }
            : {})}
          shape={renderProps.shape}
          softness={renderProps.softness}
          speed={renderProps.speed}
          width={renderProps.width}
        />
      ) : null}
    </div>
  )
}

.ts4-shader-frame {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}

.ts4-shader-canvas {
  position: absolute;
  inset: -2px;
  width: calc(100% + 4px);
  height: calc(100% + 4px);
  min-width: calc(100% + 4px);
  min-height: calc(100% + 4px);
}

.ts4-shader-frame canvas {
  display: block;
  width: 100% !important;
  height: 100% !important;
  object-fit: cover;
}

.ts4-portrait {
  filter: grayscale(1) contrast(1.15);
  mix-blend-mode: multiply;
}

@media (prefers-reduced-motion: reduce) {
  .ts4-shader-frame {
    display: none;
  }

  .ts4-portrait {
    filter: none;
    mix-blend-mode: normal;
  }
}
